-- =====================================================================
-- Cetus - billing schema (owned by Flyway; the "auth" schema belongs to Better Auth/Drizzle)
-- IDs are UUID v7 generated by the application. Money is NUMERIC, never float.
-- Secrets are stored "sealed" (KMS envelope encryption, see SecretCipher).
-- =====================================================================

CREATE TABLE accounts (
    id              UUID PRIMARY KEY,
    -- Better Auth organization id. No FK: the auth schema has its own lifecycle.
    organization_id TEXT        NOT NULL UNIQUE,
    name            TEXT        NOT NULL,
    status          TEXT        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
    plan            TEXT        NOT NULL DEFAULT 'FREE',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE api_keys (
    id              UUID PRIMARY KEY,
    account_id      UUID        NOT NULL REFERENCES accounts(id),
    environment     TEXT        NOT NULL CHECK (environment IN ('TEST', 'LIVE')),
    name            TEXT        NOT NULL,
    key_prefix      TEXT        NOT NULL,
    key_hash        TEXT        NOT NULL UNIQUE,
    last_used_at    TIMESTAMPTZ,
    revoked_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_api_keys_account ON api_keys(account_id);

CREATE TABLE issuers (
    id                   UUID PRIMARY KEY,
    account_id           UUID        NOT NULL REFERENCES accounts(id),
    environment          TEXT        NOT NULL CHECK (environment IN ('TEST', 'LIVE')),
    nit                  TEXT        NOT NULL,
    check_digit          TEXT        NOT NULL,
    legal_name           TEXT        NOT NULL,
    trade_name           TEXT,
    person_type          TEXT        NOT NULL CHECK (person_type IN ('LEGAL_ENTITY', 'NATURAL_PERSON')),
    tax_level_codes      TEXT        NOT NULL,          -- "O-13;O-15"
    tax_scheme_id        TEXT        NOT NULL DEFAULT '01',
    tax_scheme_name      TEXT        NOT NULL DEFAULT 'IVA',
    address              JSONB       NOT NULL,
    email                TEXT        NOT NULL,
    phone                TEXT,
    operation_mode       TEXT        NOT NULL CHECK (operation_mode IN ('OWN_SOFTWARE', 'TECHNOLOGY_PROVIDER')),
    status               TEXT        NOT NULL DEFAULT 'ONBOARDING'
                         CHECK (status IN ('ONBOARDING', 'TESTING', 'ENABLED', 'DISABLED')),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (account_id, environment, nit)
);

CREATE TABLE issuer_software_credentials (
    id              UUID PRIMARY KEY,
    issuer_id       UUID        NOT NULL REFERENCES issuers(id),
    software_id     TEXT        NOT NULL,
    pin_sealed      BYTEA       NOT NULL,
    test_set_id     TEXT,
    active          BOOLEAN     NOT NULL DEFAULT true,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_software_credentials_active ON issuer_software_credentials(issuer_id) WHERE active;

CREATE TABLE signing_certificates (
    id                  UUID PRIMARY KEY,
    issuer_id           UUID        NOT NULL REFERENCES issuers(id),
    s3_key              TEXT        NOT NULL,           -- sealed .p12 in S3
    password_sealed     BYTEA       NOT NULL,
    subject_dn          TEXT        NOT NULL,
    issuer_dn           TEXT        NOT NULL,
    serial_number       TEXT        NOT NULL,
    fingerprint_sha256  TEXT        NOT NULL,
    valid_from          TIMESTAMPTZ NOT NULL,
    valid_to            TIMESTAMPTZ NOT NULL,
    active              BOOLEAN     NOT NULL DEFAULT true,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_signing_certificates_active ON signing_certificates(issuer_id) WHERE active;
CREATE INDEX idx_signing_certificates_expiry ON signing_certificates(valid_to) WHERE active;

CREATE TABLE numbering_ranges (
    id                    UUID PRIMARY KEY,
    issuer_id             UUID        NOT NULL REFERENCES issuers(id),
    document_type         TEXT        NOT NULL CHECK (document_type IN ('INVOICE', 'CREDIT_NOTE', 'DEBIT_NOTE')),
    resolution_number     TEXT,
    resolution_date       DATE,
    prefix                TEXT        NOT NULL DEFAULT '',
    range_from            BIGINT      NOT NULL,
    range_to              BIGINT      NOT NULL,
    next_number           BIGINT      NOT NULL,
    valid_from            DATE,
    valid_to              DATE,
    technical_key_sealed  BYTEA,
    status                TEXT        NOT NULL DEFAULT 'ACTIVE'
                          CHECK (status IN ('ACTIVE', 'EXHAUSTED', 'EXPIRED', 'DISABLED')),
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (range_from <= range_to),
    CHECK (next_number BETWEEN range_from AND range_to + 1)
);
CREATE INDEX idx_numbering_ranges_lookup ON numbering_ranges(issuer_id, document_type, status);

-- Per issuer and year counter used in DIAN file names (fv/z + ... + 8 hex digits).
CREATE TABLE issuer_file_counters (
    issuer_id   UUID   NOT NULL REFERENCES issuers(id),
    year        INT    NOT NULL,
    last_value  BIGINT NOT NULL,
    PRIMARY KEY (issuer_id, year)
);

CREATE TABLE documents (
    id                      UUID PRIMARY KEY,
    account_id              UUID        NOT NULL REFERENCES accounts(id),
    issuer_id               UUID        NOT NULL REFERENCES issuers(id),
    environment             TEXT        NOT NULL CHECK (environment IN ('TEST', 'LIVE')),
    document_type           TEXT        NOT NULL CHECK (document_type IN ('INVOICE', 'CREDIT_NOTE', 'DEBIT_NOTE')),
    operation_type          TEXT        NOT NULL DEFAULT '10',
    numbering_range_id      UUID        NOT NULL REFERENCES numbering_ranges(id),
    prefix                  TEXT        NOT NULL,
    number                  BIGINT      NOT NULL,
    issue_date              DATE        NOT NULL,
    issue_time              TIME        NOT NULL,       -- Colombia time (UTC-05:00)
    due_date                DATE,
    currency                CHAR(3)     NOT NULL DEFAULT 'COP',
    customer                JSONB       NOT NULL,       -- immutable snapshot
    payment                 JSONB       NOT NULL,
    line_extension_amount   NUMERIC(20,2) NOT NULL,
    tax_exclusive_amount    NUMERIC(20,2) NOT NULL,
    tax_inclusive_amount    NUMERIC(20,2) NOT NULL,
    allowance_total_amount  NUMERIC(20,2) NOT NULL DEFAULT 0,
    charge_total_amount     NUMERIC(20,2) NOT NULL DEFAULT 0,
    prepaid_amount          NUMERIC(20,2) NOT NULL DEFAULT 0,
    payable_amount          NUMERIC(20,2) NOT NULL,
    referenced_document_id  UUID        REFERENCES documents(id),
    cufe                    TEXT,
    dian_track_id           TEXT,                       -- ZipKey for async test set uploads
    status                  TEXT        NOT NULL DEFAULT 'RECEIVED'
                            CHECK (status IN ('RECEIVED','PROCESSING','SUBMITTED','ACCEPTED','REJECTED','FAILED')),
    dian_status_code        TEXT,
    dian_status_message     TEXT,
    dian_errors             JSONB       NOT NULL DEFAULT '[]',
    validated_at            TIMESTAMPTZ,
    notes                   JSONB       NOT NULL DEFAULT '[]',
    request_payload         JSONB       NOT NULL,
    external_reference      TEXT,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (issuer_id, document_type, prefix, number)
);
CREATE INDEX idx_documents_account_created ON documents(account_id, created_at DESC);
CREATE INDEX idx_documents_issuer_status ON documents(issuer_id, status);
CREATE UNIQUE INDEX uq_documents_cufe ON documents(cufe) WHERE cufe IS NOT NULL;
CREATE INDEX idx_documents_external_ref ON documents(account_id, external_reference) WHERE external_reference IS NOT NULL;

CREATE TABLE document_lines (
    id                     UUID PRIMARY KEY,
    document_id            UUID          NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    line_number            INT           NOT NULL,
    item_code              TEXT,
    description            TEXT          NOT NULL,
    quantity               NUMERIC(20,6) NOT NULL,
    unit_code              TEXT          NOT NULL,
    unit_price             NUMERIC(20,6) NOT NULL,
    line_extension_amount  NUMERIC(20,2) NOT NULL,
    UNIQUE (document_id, line_number)
);

-- Line-level taxes (line_id set) and document-level totals (line_id NULL).
CREATE TABLE document_taxes (
    id              UUID PRIMARY KEY,
    document_id     UUID          NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    line_id         UUID          REFERENCES document_lines(id) ON DELETE CASCADE,
    tax_type        TEXT          NOT NULL CHECK (tax_type IN ('IVA', 'ICA', 'INC')),
    taxable_amount  NUMERIC(20,2) NOT NULL,
    percent         NUMERIC(7,2)  NOT NULL,
    tax_amount      NUMERIC(20,2) NOT NULL
);
CREATE INDEX idx_document_taxes_document ON document_taxes(document_id);

CREATE TABLE document_artifacts (
    id              UUID PRIMARY KEY,
    document_id     UUID        NOT NULL REFERENCES documents(id),
    kind            TEXT        NOT NULL CHECK (kind IN ('SIGNED_XML','ZIP','DIAN_REQUEST','DIAN_RESPONSE',
                                                        'APPLICATION_RESPONSE','ATTACHED_DOCUMENT','PDF')),
    s3_key          TEXT        NOT NULL,
    sha256          TEXT        NOT NULL,
    size_bytes      BIGINT      NOT NULL,
    content_type    TEXT        NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_document_artifacts_document ON document_artifacts(document_id, kind);

CREATE TABLE dian_submissions (
    id              UUID PRIMARY KEY,
    document_id     UUID        NOT NULL REFERENCES documents(id),
    operation       TEXT        NOT NULL,
    track_id        TEXT,
    timed_out       BOOLEAN     NOT NULL DEFAULT false,
    is_valid        BOOLEAN,
    status_code     TEXT,
    status_message  TEXT,
    errors          JSONB       NOT NULL DEFAULT '[]',
    duration_ms     INT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_dian_submissions_document ON dian_submissions(document_id, created_at);

CREATE TABLE idempotency_keys (
    account_id      UUID        NOT NULL REFERENCES accounts(id),
    idem_key        TEXT        NOT NULL,
    request_hash    TEXT        NOT NULL,
    status          TEXT        NOT NULL CHECK (status IN ('IN_PROGRESS', 'COMPLETED')),
    response_status INT,
    response_body   JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL DEFAULT now() + INTERVAL '24 hours',
    PRIMARY KEY (account_id, idem_key)
);
CREATE INDEX idx_idempotency_keys_expiry ON idempotency_keys(expires_at);

-- Transactional outbox / job queue, consumed with FOR UPDATE SKIP LOCKED.
CREATE TABLE jobs (
    id              UUID PRIMARY KEY,
    job_type        TEXT        NOT NULL,
    reference_id    UUID,
    payload         JSONB       NOT NULL DEFAULT '{}',
    status          TEXT        NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','RUNNING','DONE','DEAD')),
    attempts        INT         NOT NULL DEFAULT 0,
    max_attempts    INT         NOT NULL DEFAULT 10,
    run_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    locked_until    TIMESTAMPTZ,
    locked_by       TEXT,
    last_error      TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_jobs_ready ON jobs(run_at) WHERE status IN ('PENDING', 'RUNNING');

CREATE TABLE audit_log (
    id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    account_id      UUID,
    actor_type      TEXT        NOT NULL,
    actor_id        TEXT,
    action          TEXT        NOT NULL,
    resource_type   TEXT,
    resource_id     UUID,
    data            JSONB       NOT NULL DEFAULT '{}',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_log_account ON audit_log(account_id, created_at DESC);
